// The equal-budget direct-fix baseline (self-improve 3.3, D13). Both arms of a
// fix cycle — `direct-fix` (the baseline) and `loop-fix` (the loop's bounded
// fix) — launch through `evaluator fix`: same agent, shim, model, caps, ledger
// and cell construction; only the PROMPT differs, and only by the loop's brief.
// Everything here is pure over files and strings so the tamper fixtures can
// exercise every refusal without an agent.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { sha256 } from "./hash"
import type { Caps } from "./ledger"
import { must, run, scrubbedEnv } from "./proc"

export const FIX_ARMS = ["direct-fix", "loop-fix"] as const
export type FixArm = (typeof FIX_ARMS)[number]
/** The slot key a fix launch uses in the ledger (D12 rows carry rep + session). */
export const FIX_SLOT = "fix"

// ---------- the approved loss row (D13 §2) ----------

export interface SuggestionTrust {
  protocol: string
  verdict: string
  precision: number
  recall: number
  judged: number
}

export interface Transition {
  event: string
  type: string
  ts: string
  reason?: string
}

export interface LossRow {
  candidate: string
  scope: string
  signal: string
  count: number
  evidence: string[]
  cutoff?: string
  engine?: string
  detector_version?: number
  trust: SuggestionTrust
  proposed: Transition
  approved: Transition
  history: Transition[]
}

export type LossLookup = { ok: true; row: LossRow; scopeLog: string } | { ok: false; reason: string }

const TRANSITIONS = new Set(["suggestion_proposed", "suggestion_approved", "suggestion_rejected", "suggestion_reverted"])
const STATUS: Record<string, string> = {
  suggestion_proposed: "recorded but not approved",
  suggestion_approved: "approved",
  suggestion_rejected: "rejected",
  suggestion_reverted: "reverted",
}

/** Tolerant JSONL: a torn or foreign line is skipped, never fatal (the sofar rule for its own log). */
export function readJsonl(file: string): any[] {
  if (!existsSync(file)) return []
  const out: any[] = []
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue
    try {
      out.push(JSON.parse(line))
    } catch {}
  }
  return out
}

/**
 * The row for a candidate hash, read from the record itself: every initiative's
 * log is scanned for the candidate's transitions, and only a row whose LAST
 * transition is `suggestion_approved` may enter a fix cycle. JSON only — no
 * sofar binary interprets anything here (D9 §1 concerns results; this is input).
 */
export function findLossRow(sofarDir: string, hash: string): LossLookup {
  const initDir = join(sofarDir, "initiatives")
  if (!existsSync(initDir)) return { ok: false, reason: `no initiatives under ${sofarDir}` }
  let proposed: any = null
  let scope = ""
  const history: Transition[] = []
  for (const slug of readdirSync(initDir).sort()) {
    const file = join(initDir, slug, "events.jsonl")
    for (const e of readJsonl(file)) {
      if (!TRANSITIONS.has(e?.type) || e?.payload?.candidate !== hash) continue
      const t: Transition = { event: String(e.id), type: e.type, ts: String(e.ts) }
      if (typeof e.payload.reason === "string" && e.payload.reason) t.reason = e.payload.reason
      history.push(t)
      if (e.type === "suggestion_proposed") {
        proposed = e
        scope = slug
      }
    }
  }
  if (!proposed) return { ok: false, reason: `no suggestion_proposed for ${hash} under ${initDir} — \`sofar suggest record ${hash}\` writes one, and approval is a separate verdict` }
  history.sort((a, b) => (a.ts < b.ts ? -1 : a.ts > b.ts ? 1 : 0))
  const last = history[history.length - 1]!
  if (last.type !== "suggestion_approved") {
    return { ok: false, reason: `candidate ${hash} is ${STATUS[last.type] ?? last.type} (last transition ${last.event} at ${last.ts}); only an APPROVED row enters a fix cycle (D13 §2)` }
  }
  const p = proposed.payload
  const evidence = Array.isArray(p.evidence) ? p.evidence.map(String) : []
  const trust = p.trust ?? {}
  const row: LossRow = {
    candidate: hash,
    scope,
    signal: String(p.signal ?? "?"),
    count: Number(p.count ?? evidence.length),
    evidence,
    trust: { protocol: String(trust.protocol ?? "?"), verdict: String(trust.verdict ?? "?"), precision: Number(trust.precision), recall: Number(trust.recall), judged: Number(trust.judged) },
    proposed: history.find((t) => t.type === "suggestion_proposed")!,
    approved: last,
    history,
  }
  if (typeof p.cutoff === "string") row.cutoff = p.cutoff
  if (typeof p.engine === "string") row.engine = p.engine
  if (typeof p.detector_version === "number") row.detector_version = p.detector_version
  return { ok: true, row, scopeLog: join(initDir, scope, "events.jsonl") }
}

const CLIP = 400
const clip = (s: string) => (s.length > CLIP ? `${s.slice(0, CLIP)}…` : s)
const one = (s: unknown) => String(s ?? "").replace(/\s+/g, " ").trim()

/** One line of what an event said, by type — enough for a reader to see the loss, never the whole payload. */
export function evidenceText(e: any): string {
  const p = e?.payload ?? {}
  switch (e?.type) {
    case "correction":
      return clip(`correction of ${p.ref}${p.reason ? `: ${one(p.reason)}` : ""}`)
    case "note_added":
      return clip(`note: ${one(p.text)}`)
    case "decision_logged":
      return clip(`decision: chose ${one(p.chose)}`)
    case "session_ended":
      return clip(`write-back: ${one(p.summary)} → next: ${one(p.next_action)}`)
    case "task_status_changed":
      return clip(`task ${p.task_id} → ${p.status}${p.note ? `: ${one(p.note)}` : ""}`)
    case "command_run":
      return clip(`command: ${one(p.cmd)}`)
    case "file_touched":
      return clip(`file: ${one(p.path)}`)
    case "memory_promoted":
      return clip(`memory: ${one(p.text)}`)
    default:
      return clip(`${one(JSON.stringify(p))}`)
  }
}

/** The evidence events the row cites, from the scope's log. Ids not in the record stay unresolved, and say so. */
export function resolveEvidence(scopeLog: string, ids: string[]): Map<string, any | null> {
  const want = new Set(ids)
  const found = new Map<string, any>()
  for (const e of readJsonl(scopeLog)) if (want.has(e?.id)) found.set(e.id, e)
  return new Map(ids.map((id) => [id, found.get(id) ?? null]))
}

/** Byte-identical for both arms; its sha256 is in every result (D13 §2). */
export function renderLossRow(row: LossRow, evidence: Map<string, any | null>): string {
  const t = row.trust
  const lines = [
    `Loss row ${row.candidate} — signal "${row.signal}", scope "${row.scope}" (initiative ${row.scope} in this repo's .sofar record)`,
    `Approved ${row.approved.ts} (event ${row.approved.event})${row.approved.reason ? `: ${one(row.approved.reason)}` : ""}; proposed ${row.proposed.ts} (event ${row.proposed.event})`,
    `Detector trust (self-improve 2.2 protocol ${t.protocol}, verdict ${t.verdict}): precision ${t.precision}, recall ${t.recall} over ${t.judged} judged findings.`,
    `${row.count} instance(s); ${row.evidence.length} evidence entries the detector cited:`,
  ]
  for (const id of row.evidence) {
    const e = evidence.get(id)
    if (!e) lines.push(`- ${id}: ${id.startsWith("row:") ? "a private diagnostics row, not in the record" : "not found in the record"}`)
    else lines.push(`- ${id} ${e.ts} ${e.type}: ${evidenceText(e)}`)
  }
  return `${lines.join("\n")}\n`
}

// ---------- the prompt (D13 §1, §4) ----------

export interface PromptInput {
  arm: FixArm
  base: string
  rowText: string
  /** loop-fix only: the loop's brief, verbatim. */
  brief?: string
}

/** direct-fix is a strict prefix of loop-fix: the brief is the ONLY difference between arms. */
export function composeFixPrompt(o: PromptInput): string {
  const parts = [
    `You are working in a checkout of the sofar repository at commit ${o.base} (the only commit in this repo). One loss recorded by sofar's own improvement process is below. Make a bounded change to sofar that removes or reduces this loss.`,
    o.rowText.trimEnd(),
    [
      "Rules:",
      "- Read CLAUDE.md and docs/SPEC.md first; follow the repo's conventions and its sofar protocol.",
      "- Keep the change bounded: the smallest change that addresses the loss row, with tests for it.",
      "- Feedback you may use: this repo's own suite — `npm test`, `npm run typecheck`, `npm run build`. Nothing outside this directory is part of the task.",
      "- Never edit or delete existing tests to make them pass.",
      "- Commit your work with git before you finish (any message). Uncommitted work is discarded.",
    ].join("\n"),
  ]
  if (o.arm === "loop-fix" && o.brief !== undefined) parts.push(`Brief from the improvement loop:\n${o.brief.trimEnd()}`)
  return `${parts.join("\n\n")}\n`
}

// ---------- the refless cell (D13 §3) ----------

const GIT_ENV = () => scrubbedEnv({ GIT_AUTHOR_NAME: "evaluator", GIT_AUTHOR_EMAIL: "evaluator@localhost", GIT_COMMITTER_NAME: "evaluator", GIT_COMMITTER_EMAIL: "evaluator@localhost" })

export async function gitOut(cwd: string, args: string[], what: string): Promise<string> {
  return (await must(["git", ...args], { cwd, env: GIT_ENV(), timeoutMs: 120_000 }, what)).stdout.trim()
}

/** Every worktree of a repo, the main one first — all of them are hidden from a fix cell. */
export async function worktreesOf(repo: string): Promise<string[]> {
  const out = await gitOut(repo, ["worktree", "list", "--porcelain"], "git worktree list")
  return out
    .split("\n")
    .filter((l) => l.startsWith("worktree "))
    .map((l) => l.slice("worktree ".length).trim())
}

/** Every local branch tip other than the base commit: a sha the agent can only utter if it reached the hidden history. */
export async function hiddenTipShas(repo: string, base: string): Promise<string[]> {
  const out = await gitOut(repo, ["for-each-ref", "--format=%(objectname)", "refs/heads"], "git for-each-ref")
  return [...new Set(out.split("\n").filter((s) => /^[0-9a-f]{40}$/.test(s) && s !== base))]
}

/**
 * `git archive` of one commit into a fresh `git init` repo with ONE commit:
 * no refs, reflog or objects beyond that tree, so the comparator branch is
 * unreachable through git. Hidden record initiatives are removed before the
 * commit, so the human plan for the comparator is not in the cell either.
 */
export async function exportCell(o: { repo: string; commit: string; dest: string; hideRecords: string[] }): Promise<{ head: string; removed: string[] }> {
  mkdirSync(o.dest, { recursive: true })
  const tar = join(dirname(o.dest), `base-${o.commit.slice(0, 12)}.tar`)
  await must(["git", "archive", "--format=tar", "-o", tar, o.commit], { cwd: o.repo, timeoutMs: 120_000 }, "git archive")
  await must(["tar", "-xf", tar, "-C", o.dest], { cwd: dirname(o.dest), timeoutMs: 120_000 }, "tar -x")
  rmSync(tar, { force: true })
  const removed: string[] = []
  for (const slug of o.hideRecords) {
    const dir = join(o.dest, ".sofar", "initiatives", slug)
    if (existsSync(dir)) {
      rmSync(dir, { recursive: true, force: true })
      removed.push(slug)
    }
  }
  const env = GIT_ENV()
  await must(["git", "init", "-q", "-b", "main"], { cwd: o.dest, env, timeoutMs: 60_000 }, "git init")
  await must(["git", "add", "-A"], { cwd: o.dest, env, timeoutMs: 120_000 }, "git add")
  await must(["git", "commit", "-q", "-m", `base: ${o.commit}`], { cwd: o.dest, env, timeoutMs: 120_000 }, "git commit")
  const head = await gitOut(o.dest, ["rev-parse", "HEAD"], "git rev-parse")
  return { head, removed }
}

/** Claude's per-cell settings, as the runner writes them (bench-refresh D15): no auto memory across cells. */
export function writeCellSettings(repo: string): void {
  mkdirSync(join(repo, ".claude"), { recursive: true })
  writeFileSync(join(repo, ".claude", "settings.local.json"), `${JSON.stringify({ autoMemoryEnabled: false }, null, 2)}\n`)
  mkdirSync(join(repo, ".git", "info"), { recursive: true })
  writeFileSync(join(repo, ".git", "info", "exclude"), ".claude/settings.local.json\n", { flag: "a" })
}

/** Commit whatever the session left; report whether anything changed against the base commit. */
export async function commitFix(repo: string, baseHead: string, label: string): Promise<{ head: string; changed: boolean; diffstat: string }> {
  const env = GIT_ENV()
  await must(["git", "add", "-A"], { cwd: repo, env, timeoutMs: 120_000 }, "git add")
  await must(["git", "commit", "-q", "--allow-empty", "-m", `fix: ${label}`], { cwd: repo, env, timeoutMs: 120_000 }, "git commit")
  const head = await gitOut(repo, ["rev-parse", "HEAD"], "git rev-parse")
  const diffstat = await gitOut(repo, ["diff", "--stat", `${baseHead}..HEAD`], "git diff --stat")
  return { head, changed: diffstat.length > 0, diffstat }
}

/** Discard a lost attempt's partial work: back to the base commit, untracked files gone, node_modules kept. */
export async function resetFixCell(repo: string, baseHead: string): Promise<void> {
  await run(["git", "reset", "-q", "--hard", baseHead], { cwd: repo, env: GIT_ENV(), timeoutMs: 120_000 })
  await run(["git", "clean", "-qfd"], { cwd: repo, env: GIT_ENV(), timeoutMs: 120_000 })
}

// ---------- the transcript scan (D13 §3) ----------

export interface Scan {
  /** Terms whose presence VOIDS the attempt: hidden branch-tip shas and --hidden-term. */
  voiding: string[]
  /** Hidden paths mentioned — a warning, never a void: the kernel denied the read, and the record itself names paths. */
  mentioned: string[]
}

export function scanTranscript(text: string, o: { voidTerms: string[]; warnTerms: string[] }): Scan {
  const hit = (t: string) => t.length >= 7 && text.includes(t)
  return { voiding: o.voidTerms.filter(hit), mentioned: o.warnTerms.filter(hit) }
}

// ---------- equal parameters and the verdict (D13 §1, §6, §7) ----------

export interface FixRunJson {
  mode: "fix"
  run: string
  arm: FixArm
  loss: { candidate: string; scope: string; signal: string; approved_event: string }
  row_sha256: string
  prompt_sha256: string
  brief_sha256: string | null
  base_commit: string
  source_repo: string
  hidden: { paths: string[]; records: string[]; void_terms: number }
  model: string
  effort: string
  timeout_min: number
  reps: number
  pin_hash: string
  evaluator: { commit: string; dirty: string[] }
  budget: Caps
  started_at: string
}

/** Everything that must match between the two arms; the brief and the hidden set may differ. */
export function unequalParams(a: FixRunJson, b: FixRunJson): string[] {
  const out: string[] = []
  const cmp = (name: string, x: unknown, y: unknown) => {
    if (JSON.stringify(x) !== JSON.stringify(y)) out.push(`${name}: ${JSON.stringify(x)} vs ${JSON.stringify(y)}`)
  }
  cmp("base_commit", a.base_commit, b.base_commit)
  cmp("loss.candidate", a.loss.candidate, b.loss.candidate)
  cmp("row_sha256", a.row_sha256, b.row_sha256)
  cmp("model", a.model, b.model)
  cmp("effort", a.effort, b.effort)
  cmp("timeout_min", a.timeout_min, b.timeout_min)
  cmp("reps", a.reps, b.reps)
  cmp("pin_hash", a.pin_hash, b.pin_hash)
  cmp("evaluator.commit", a.evaluator.commit, b.evaluator.commit)
  return out
}

export interface RepSummary {
  rep: number
  candidate: string | null
  voided: string | null
  changed: boolean
  eval_run?: string
  sessions?: string[]
  pass?: number
  fail?: number
}

export interface ArmSummary {
  arm: FixArm
  run: string
  reps: RepSummary[]
  fix_launches: number
  fix_charged_usd: number
  fix_reported_usd: number
  eval_charged_usd: number
  time_ms: number
  cap_usd: number
  /** Mean hidden-test pass over reps; null when any rep has no score. */
  mean_pass: number | null
}

export function meanPass(reps: RepSummary[]): number | null {
  if (reps.length === 0 || reps.some((r) => r.pass === undefined)) return null
  return reps.reduce((n, r) => n + (r.pass ?? 0), 0) / reps.length
}

export interface Verdict {
  kind: "keep" | "discard" | "withheld"
  reason: string
  loop_full_cost_usd: number | null
  baseline_cap_usd: number
  cost_delta_usd: number | null
}

/**
 * KEEP only when the loop's mean pass is STRICTLY above the baseline's at a
 * baseline cap that covers the loop's full cost; any unequal parameter, voided
 * rep, missing score or unstated loop cost withholds the verdict (D13 §7).
 */
export function verdict(o: { loop: ArmSummary; baseline: ArmSummary; loopExtraUsd: number | null; unequal: string[] }): Verdict {
  const cap = o.baseline.cap_usd
  const fullCost = o.loopExtraUsd === null ? null : o.loop.fix_charged_usd + o.loopExtraUsd
  const costDelta = fullCost === null ? null : fullCost + o.loop.eval_charged_usd - (o.baseline.fix_charged_usd + o.baseline.eval_charged_usd)
  const withheld = (reason: string): Verdict => ({ kind: "withheld", reason, loop_full_cost_usd: fullCost, baseline_cap_usd: cap, cost_delta_usd: costDelta })
  if (o.unequal.length) return withheld(`unequal parameters — ${o.unequal.join("; ")}`)
  if (o.loopExtraUsd === null) return withheld("the loop's cost outside the evaluator is unstated — pass --loop-extra-usd (0 is allowed, silence is not)")
  for (const arm of [o.loop, o.baseline]) {
    for (const r of arm.reps) {
      if (r.voided) return withheld(`${arm.arm} r${r.rep} was voided: ${r.voided}`)
      if (r.candidate === null) return withheld(`${arm.arm} r${r.rep} produced no candidate`)
      if (r.pass === undefined) return withheld(`${arm.arm} r${r.rep} (${r.candidate}) has no evaluation run with an ok verdict — \`evaluator run --candidate ${r.candidate} …\` first`)
    }
    if (arm.reps.length === 0) return withheld(`${arm.arm} has no reps`)
  }
  const sessionSets = new Set([...o.loop.reps, ...o.baseline.reps].map((r) => JSON.stringify(r.sessions ?? [])))
  if (sessionSets.size !== 1) return withheld(`reps were scored on different session sets: ${[...sessionSets].join(" vs ")}`)
  if (cap < (fullCost as number)) return withheld(`baseline cap $${cap.toFixed(2)} is below the loop's full cost $${(fullCost as number).toFixed(2)} (fix launches $${o.loop.fix_charged_usd.toFixed(2)} + stated extra $${(o.loopExtraUsd as number).toFixed(2)}); rerun the baseline with --max-usd ≥ that (D13 §6)`)
  const lp = o.loop.mean_pass as number
  const bp = o.baseline.mean_pass as number
  const line = `loop mean pass ${lp.toFixed(2)} vs baseline ${bp.toFixed(2)} at baseline cap $${cap.toFixed(2)} ≥ loop full cost $${(fullCost as number).toFixed(2)}`
  if (lp > bp) return { kind: "keep", reason: `${line}: the loop wins strictly`, loop_full_cost_usd: fullCost, baseline_cap_usd: cap, cost_delta_usd: costDelta }
  return { kind: "discard", reason: `${line}: ${lp === bp ? "a tie loses" : "the baseline wins"}`, loop_full_cost_usd: fullCost, baseline_cap_usd: cap, cost_delta_usd: costDelta }
}

/** Hash helper for briefs and rows. */
export function shaOf(text: string | null): string | null {
  return text === null ? null : sha256(text)
}
