  const lookup = findLossRow(join(repo, ".sofar"), values.loss)
  if (!lookup.ok) throw new Refusal(`loss row refused: ${lookup.reason}`, { loss: values.loss, repo })
  const row = lookup.row
  const rowText = renderLossRow(row, resolveEvidence(lookup.scopeLog, row.evidence))
  const base = await gitOut(repo, ["rev-parse", `${values.base ?? "HEAD"}^{commit}`], "git rev-parse")
  const reps = Number(values.reps)
  const hidePaths = [...new Set([repo, ...(await worktreesOf(repo)), ...listArg("hide")].map(profilePath))]
  const hideRecords = listArg("hide-record")
  const voidTerms = [...(await hiddenTipShas(repo, base)), ...listArg("hidden-term")]
  const prompt = composeFixPrompt({ arm, base, rowText, brief: brief ?? undefined })
  const rowSha = sha256(rowText)
  const briefSha = shaOf(brief)

  const runId = values.run ?? `fix-${arm}-${row.candidate.slice(0, 8)}-${startedAt.replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z")}`
  const runDir = join(RUNS, runId)
  const cellsDir = join(runDir, "cells")
  const resultsDir = join(runDir, "results")
  const sandboxDir = join(runDir, "sandbox")
  const resuming = values.resume
  if (existsSync(runDir) && !resuming) throw new Refusal(`run ${runId} already exists (pass --resume to continue it)`, runDir)
  if (resuming) {
    if (!existsSync(join(resultsDir, "run.json"))) throw new Refusal(`nothing to resume at ${runDir}`, runDir)
    const prev = JSON.parse(readFileSync(join(resultsDir, "run.json"), "utf8"))
    const same = prev.mode === "fix" && prev.arm === arm && prev.loss?.candidate === row.candidate && prev.base_commit === base && prev.reps === reps && prev.pin_hash === pinH && prev.row_sha256 === rowSha && prev.brief_sha256 === briefSha && prev.model === values.model && prev.effort === values.effort
    if (!same) throw new Refusal("resume refused: arm, loss, base, reps, pin, row text, brief, model or effort differ from the run being resumed", { previous: { arm: prev.arm, loss: prev.loss?.candidate, base: prev.base_commit, reps: prev.reps, pin_hash: prev.pin_hash, row_sha256: prev.row_sha256, brief_sha256: prev.brief_sha256, model: prev.model, effort: prev.effort } })
  }
  for (const d of [cellsDir, resultsDir, sandboxDir]) mkdirSync(d, { recursive: true })

  const unreadable = [...SEALED_FOR_CANDIDATE(), resultsDir, ...hidePaths]
  const profileText = candidateProfile({ writable: [cellsDir, CLAUDE_CONFIG, SOFAR_STATE, ...TMP_WRITABLE, ...CACHE_WRITABLE], unreadable })
  const profile = writeProfile(sandboxDir, "candidate.sb", profileText)
  const probes: Probe[] = [
    ...standardProbes({ hiddenTests: P.hiddenTests, sealed: SEALED, reference: REFERENCE_A, results: resultsDir, evaluatorRepo: EVALUATOR_REPO, runnerLib: P.runnerLib, cell: cellsDir }),
    ...hidePaths.map((p) => ({ name: `read hidden ${p}`, cmd: `ls ${p} > /dev/null`, expect: "deny" as const })),
  ]
  const probeResults = await selfTest(profile, probes)
  writeJson(join(resultsDir, resuming ? `selftest-resume-${Date.now()}.json` : "selftest.json"), probeResults)
  const badProbes = probeResults.filter((r) => !r.ok)
  if (badProbes.length) throw new Refusal("sandbox self-test failed; nothing launched", badProbes)
  log(`sandbox self-test: all ${probeResults.length} probes hold (${hidePaths.length} hidden path(s) unreadable)`)

  const claudeBin = Bun.which("claude")
  const nodeBin = Bun.which("node")
  if (!claudeBin || !nodeBin) throw new Error("claude or node not on PATH")
  // No candidate sofar exists yet: the cell's hooks and MCP reach the runner's pinned install, sandboxed by inheritance.
  const shims = writeShims(join(runDir, "shims"), { profileFile: profile, claudeBin, nodeBin })
  process.env.PATH = `${shims.binDir}:${process.env.PATH ?? ""}`
  const runner = await loadRunner(P.runnerLib)
  const fixArm = {
    id: arm,
    agent: "claude-code",
    store: null,
    setup: async () => {},
    mcpConfig: ({ repo: r, cellDir }: { repo: string; cellDir: string }) => {
      if (existsSync(join(r, ".mcp.json"))) return join(r, ".mcp.json")
      const file = join(cellDir, "mcp-empty.json")
      writeFileSync(file, JSON.stringify({ mcpServers: {} }))
      return file
    },
  }
  const cfg = { models: { "claude-code": values.model }, efforts: { "claude-code": values.effort }, sessionTimeoutMs: Number(values["timeout-min"]) * 60_000 }
  const budget = { ...caps(), maxLaunches: values["max-launches"] ? Number(values["max-launches"]) : reps }
  const base_: FixRunJson & Record<string, unknown> = {
    mode: "fix",
    run: runId,
    arm,
    loss: { candidate: row.candidate, scope: row.scope, signal: row.signal, approved_event: row.approved.event },
    row_sha256: rowSha,
    prompt_sha256: sha256(prompt),
    brief_sha256: briefSha,
    base_commit: base,
    source_repo: repo,
    hidden: { paths: hidePaths, records: hideRecords, void_terms: voidTerms.length },
    model: values.model as string,
    effort: values.effort as string,
    timeout_min: Number(values["timeout-min"]),
    reps,
    pin_hash: pinH,
    evaluator: { commit: evaluator.commit, dirty: evaluator.dirty },
    budget,
    started_at: startedAt,
    pinned_handoff_bench: pin.handoff_bench_commit,
    sandbox: { profile_sha256: sha256(profileText), shims: shims.files.map((f) => ({ file: f, sha256: sha256File(f) })) },
    ledger: LEDGER_FILE,
    tools: pin.tools,
  }
  writeFileSync(join(resultsDir, "loss-row.txt"), rowText)
  writeFileSync(join(resultsDir, "prompt.txt"), prompt)
  if (brief !== null) writeFileSync(join(resultsDir, "brief.txt"), brief)
  const runJson = (extra: Record<string, unknown>) => writeJson(join(resultsDir, "run.json"), { ...base_, dry_run: values["dry-run"], ...extra })
  runJson({})
  log(`fix ${runId}${resuming ? " (RESUMED)" : ""}: arm ${arm}, loss ${row.candidate} (${row.signal} in ${row.scope}, approved ${row.approved.ts}), base ${base.slice(0, 7)} of ${repo}, reps ${reps}${values["dry-run"] ? ", DRY RUN (no agent launch)" : ""}`)
  log(`row ${rowSha.slice(0, 12)} (${rowText.length} chars), prompt ${sha256(prompt).slice(0, 12)}${briefSha ? `, brief ${briefSha.slice(0, 12)}` : ""}; hidden: ${hidePaths.length} path(s), ${hideRecords.length} record(s), ${voidTerms.length} voiding term(s)`)
  log(`budget: --max-usd $${budget.runMaxUsd}, --max-launches ${budget.maxLaunches}, rolling $${budget.weekUsd}/7d and $${budget.windowUsd}/5h over evaluator + round ledgers, unknown or lost attempts charged $${budget.nextSessionUsd} each (D12)`)

  const resultFile = (rep: number) => join(resultsDir, `${arm}-r${rep}-fix.json`)
  const slots = Array.from({ length: reps }, (_, i) => ({ rep: i + 1, session: FIX_SLOT }))
  const plan = resumePlan(readRows(), runId, slots, (rep) => existsSync(resultFile(rep)))
  if (resuming) log(`resume: ${plan.filter((p) => p.state === "done").length} rep(s) done, ${plan.filter((p) => p.state === "open").length} open (lost), ${plan.filter((p) => p.state === "pending").length} pending`)

  for (const slot of plan) {
    const { rep } = slot
    const dir = join(cellsDir, arm, `r${rep}`)
    const paths = { dir, repo: join(dir, "repo"), artifacts: join(dir, "artifacts") }
    const cellFile = join(dir, "cell.json")
    if (slot.state === "done") {
      log(`  r${rep}: already done, skipped`)
      continue
    }
    let baseHead: string
    if (!existsSync(join(paths.repo, ".git"))) {
      mkdirSync(paths.artifacts, { recursive: true })
      log(`cell ${arm}/r${rep}: export ${base.slice(0, 7)} into a refless repo${hideRecords.length ? ` without records ${hideRecords.join(", ")}` : ""}`)
      const ex = await exportCell({ repo, commit: base, dest: paths.repo, hideRecords })
      writeCellSettings(paths.repo)
      log(`cell ${arm}/r${rep}: npm ci (sandboxed)`)
      await must(sandboxed(profile, ["npm", "ci", "--no-audit", "--no-fund"]), { cwd: paths.repo, timeoutMs: 900_000 }, "npm ci")
      writeJson(cellFile, { base, head: ex.head, removed: ex.removed })
      baseHead = ex.head
    } else {
      baseHead = JSON.parse(readFileSync(cellFile, "utf8")).head
      if (slot.state === "open") {
        await resetFixCell(paths.repo, baseHead)
        log(`cell ${arm}/r${rep}: partial work of the lost attempt discarded (reset to the base commit)`)
      }
    }
    if (slot.state === "open" && slot.openIntent) {
      appendRow({ kind: "launch_lost", intent: slot.openIntent.id, run: runId, arm, rep, session: FIX_SLOT, reason: "intent never closed; charged at the next-session [redacted] })
      appendAttempt(resultsDir, { phase: "lost", run: runId, arm, rep, session: FIX_SLOT, intent: slot.openIntent.id })
    }
    const tag = `${arm}-r${rep}-fix`
    if (values["dry-run"]) {
      log(`  r${rep}: cell ready at ${paths.repo} (base ${baseHead.slice(0, 7)}); dry run, not launched`)
      continue
    }
    const now = Date.now()
    const check = capCheck(readRows(), runId, budget, { weekUsd: roundClaudeSpend(now - 7 * 86_400_000), windowUsd: roundClaudeSpend(now - 5 * 3_600_000) }, now)
    log(`  r${rep}: run charged $${check.run.charged_usd.toFixed(2)} over ${check.run.attempts} attempt(s); 7d $${(check.week_evaluator_usd + check.week_round_usd).toFixed(2)} (evaluator $${check.week_evaluator_usd.toFixed(2)}), 5h $${(check.window_evaluator_usd + check.window_round_usd).toFixed(2)}`)
    if (!check.ok) {
      appendRow({ kind: "stop", run: runId, reason: "budget_pause", detail: check.reason })
      writeJson(join(resultsDir, `stop-${Date.now()}.json`), { reason: "budget_pause", at: new Date().toISOString(), detail: check.reason, check })
      log(`BUDGET PAUSE (D12): ${check.reason}. Resume with --resume once it fits, or raise the cap explicitly.`)
      runJson({ paused_at: new Date().toISOString(), pause: check.reason })
      return 4
    }
    const intent = appendRow({ kind: "launch_intent", run: runId, arm, rep, session: FIX_SLOT, model: values.model })
    appendAttempt(resultsDir, { phase: "launch", run: runId, arm, rep, session: FIX_SLOT, model: values.model, effort: values.effort, intent: intent.id })
    const t0 = new Date().toISOString()
    let outcome: any
    try {
      outcome = await runner.launch(fixArm, paths, prompt, cfg)
    } catch (err) {
      if (err instanceof runner.BillingStop) {
        appendRow({ kind: "launch_outcome", intent: intent.id, run: runId, arm, rep, session: FIX_SLOT, ok: false, cost_usd: null, reason: "billing_stop" })
        appendRow({ kind: "stop", run: runId, reason: "billing_stop", detail: String(err.message).slice(0, 500) })
        appendAttempt(resultsDir, { phase: "billing_stop", run: runId, arm, rep, session: FIX_SLOT, evidence: String(err.message).slice(0, 500) })
        writeJson(join(resultsDir, "stop.json"), { reason: "billing_stop", at: new Date().toISOString(), evidence: String(err.message).slice(0, 2000) })
        log(`BILLING/LIMIT STOP (bench-refresh D14): ${err.message}`)
        return 3
      }
      throw err
    }
    const u = outcome.usage
    appendRow({
      kind: "launch_outcome",
      intent: intent.id,
      run: runId,
      arm,
      rep,
      session: FIX_SLOT,
      ok: outcome.ok,
      timed_out: outcome.timedOut,
      exit: outcome.exitCode,
      ms: outcome.ms,
      turns: outcome.turns,
      tokens: u ? { input: u.input_tokens, cache_creation: u.cache_creation_tokens, cache_read: u.cache_read_tokens, output: u.output_tokens } : null,
      cost_usd: typeof u?.reported_cost_usd === "number" ? u.reported_cost_usd : null,
    })
    appendAttempt(resultsDir, { phase: "launched", run: runId, arm, rep, session: FIX_SLOT, intent: intent.id, ok: outcome.ok, timedOut: outcome.timedOut, exit: outcome.exitCode, ms: outcome.ms, turns: outcome.turns, usage: u })
    const logDir = join(resultsDir, tag)
    mkdirSync(logDir, { recursive: true })
    const stdout = outcome.raw?.stdout ?? ""
    const stderr = outcome.raw?.stderr ?? ""
    writeFileSync(join(logDir, "agent.stdout.json"), stdout)
    writeFileSync(join(logDir, "agent.stderr.txt"), stderr)
    const commit = await commitFix(paths.repo, baseHead, `${arm} r${rep}`)
    const scan = scanTranscript(`${stdout}\n${stderr}`, { voidTerms, warnTerms: hidePaths })
    log(`  r${rep}: agent ${outcome.ok ? "ok" : "FAILED"} in ${Math.round(outcome.ms / 1000)}s, ${outcome.turns ?? "?"} turns, cost ${u?.reported_cost_usd ?? "unknown"}; ${commit.changed ? `changed (${commit.diffstat.split("\n").pop()?.trim()})` : "NO CHANGE"}`)
    if (scan.mentioned.length) log(`  r${rep}: transcript mentions ${scan.mentioned.length} hidden path(s) — a mention, not a read; the kernel denied those (warning only)`)
    let candidate: string | null = null
    let voided: string | null = null
    let packError: string | null = null
    if (scan.voiding.length) {
      voided = `transcript names hidden history: ${scan.voiding.map((t) => t.slice(0, 12)).join(", ")}`
      log(`  r${rep}: VOIDED — ${voided}`)
    } else {
      const tp = Date.now()
      try {
        const info = await packCandidate({ repo: paths.repo, ref: "HEAD", unreadable, log })
        appendRow({ kind: "pack", run: runId, arm, rep, session: FIX_SLOT, candidate: info.id, ms: Date.now() - tp, detail: { commit: info.commit, version: info.version } })
        candidate = info.id
      } catch (err) {
        packError = String(err instanceof Error ? err.message : err).slice(0, 2000)
        appendRow({ kind: "pack", run: runId, arm, rep, session: FIX_SLOT, ms: Date.now() - tp, reason: "pack_failed", detail: packError.slice(0, 500) })
        log(`  r${rep}: the fix does not build or pack — scored 0, not withheld (D13 §7): ${packError.split("\n")[0]}`)
      }
    }
    const result = {
      ...base_,
      rep,
      intent: intent.id,
      started_at: t0,
      ended_at: new Date().toISOString(),
      agent: { ok: outcome.ok, timedOut: outcome.timedOut, exitCode: outcome.exitCode, ms: outcome.ms, turns: outcome.turns, sessionId: outcome.sessionId, usage: u },
      cell: { base_head: baseHead, head: commit.head, changed: commit.changed, diffstat: commit.diffstat },
      scan,
      candidate,
      voided,
      pack_error: packError,
    }
    const h = writeJson(resultFile(rep), result)
    log(`  r${rep}: ${candidate ? `candidate ${candidate}` : voided ? "voided" : "no candidate"} → ${tag}.json (${h.slice(0, 12)})${candidate ? `; score it with: evaluator run --candidate ${candidate} --sessions [redacted] : ""}`)
  }
  const final = spend(attempts(readRows(), budget.nextSessionUsd), { run: runId })
  runJson({ ended_at: new Date().toISOString(), spend: final })
  log(`fix ${runId} complete: ${final.attempts} attempt(s), reported $${final.reported_usd.toFixed(2)}, charged $${final.charged_usd.toFixed(2)} (${final.unknown_n} unknown, ${final.lost_n} lost)`)
  return 0
}

// ---------- compare: the verdict over two fix runs and their evaluation runs (D13 §6, §7) ----------

function readRunJson(run: string): any | null {
  const f = join(RUNS, run, "results", "run.json")
  return existsSync(f) ? JSON.parse(readFileSync(f, "utf8")) : null
}

/** The latest evaluation run of a candidate, with the final (cumulative) ok score of each rep. */
function evalScores(candidate: string): { run: string; sessions: string[]; reps: Array<{ rep: number; pass: number; fail: number }> } | null {
  if (!existsSync(RUNS)) return null
  const found: Array<{ run: string; started: string; sessions: string[]; reps: Array<{ rep: number; pass: number; fail: number }> }> = []
  for (const run of readdirSync(RUNS)) {
    const rj = readRunJson(run)
    if (!rj || rj.mode === "fix" || rj.candidate?.id !== candidate || rj.dry_run) continue
    const dir = join(RUNS, run, "results")
    const best = new Map<number, { rep: number; pass: number; fail: number; n: number }>()
    for (const f of readdirSync(dir)) {
      const m = /^(.+)-r(\d+)-(S\d+)\.json$/.exec(f)
      if (!m) continue
      const r = JSON.parse(readFileSync(join(dir, f), "utf8"))
      if (r.score?.verdict?.kind !== "ok") continue
      const rep = Number(m[2])
      const n = (r.sessions_scored ?? []).length
      const prev = best.get(rep)
      if (!prev || n > prev.n) best.set(rep, { rep, pass: r.score.verdict.pass, fail: r.score.verdict.fail, n })
    }
    if (best.size) found.push({ run, started: String(rj.started_at ?? ""), sessions: rj.sessions ?? [], reps: [...best.values()].sort((a, b) => a.rep - b.rep).map(({ n: _n, ...r }) => r) })
  }
  if (!found.length) return null
  found.sort((a, b) => (a.started < b.started ? 1 : -1))
  const latest = found[0]!
  return { run: latest.run, sessions: latest.sessions, reps: latest.reps }
}

function summarizeFixRun(run: string, est: number): { rj: FixRunJson; summary: ArmSummary } {
  const rj = readRunJson(run)
  if (!rj) throw new Error(`no run ${run} under ${RUNS}`)
  if (rj.mode !== "fix") throw new Error(`${run} is not a fix run (mode ${rj.mode ?? "run"})`)
  const rows = readRows()
  const list = attempts(rows, est)
  const evalRuns = new Set<string>()
  const reps: RepSummary[] = []
  for (let rep = 1; rep <= rj.reps; rep++) {
    const f = join(RUNS, run, "results", `${rj.arm}-r${rep}-fix.json`)
    const fr = existsSync(f) ? JSON.parse(readFileSync(f, "utf8")) : null
    const summary: RepSummary = { rep, candidate: fr?.candidate ?? null, voided: fr?.voided ?? null, changed: fr?.cell?.changed === true, pack_failed: typeof fr?.pack_error === "string" }
    if (summary.candidate) {
      const ev = evalScores(summary.candidate)
      if (ev) {
        evalRuns.add(ev.run)
        summary.eval_run = ev.run
        summary.sessions = ev.sessions
        summary.pass = ev.reps.reduce((n, r) => n + r.pass, 0) / ev.reps.length
        summary.fail = ev.reps.reduce((n, r) => n + r.fail, 0) / ev.reps.length
      }
    }
    reps.push(summary)
  }
  const fix = spend(list, { run })
  const evalCharged = [...evalRuns].reduce((n, r) => n + spend(list, { run: r }).charged_usd, 0)
  const timeMs = rows.filter((r) => r.run === run || (r.run && evalRuns.has(r.run))).reduce((n, r) => n + (r.ms ?? 0), 0)
  return {
    rj,
    summary: { arm: rj.arm, run, reps, fix_launches: fix.attempts, fix_charged_usd: fix.charged_usd, fix_reported_usd: fix.reported_usd, eval_charged_usd: evalCharged, time_ms: timeMs, cap_usd: Number(rj.budget?.runMaxUsd ?? 0), mean_pass: meanPass(reps) },
  }
}

function cmdCompare(): number {
  if (!values.loop || !values.baseline) throw new Error("compare needs --loop <fix-run> --baseline <fix-run>")
  const est = Number(values["next-session-usd"])
  const loop = summarizeFixRun(values.loop, est)
  const baseline = summarizeFixRun(values.baseline, est)
  if (loop.rj.arm !== "loop-fix") throw new Error(`--loop ${values.loop} is arm ${loop.rj.arm}, expected loop-fix`)
  if (baseline.rj.arm !== "direct-fix") throw new Error(`--baseline ${values.baseline} is arm ${baseline.rj.arm}, expected direct-fix`)
  const extra = values["loop-extra-usd"] === undefined ? null : Number(values["loop-extra-usd"])
  if (extra !== null && !(extra >= 0)) throw new Error("--loop-extra-usd must be a number ≥ 0")
  const unequal = unequalParams(loop.rj, baseline.rj)
  const v = fixVerdict({ loop: loop.summary, baseline: baseline.summary, loopExtraUsd: extra, unequal })
  const also = listArg("also").map((c) => ({ candidate: c, eval: evalScores(c) }))
  const report = { loss: loop.rj.loss, base_commit: loop.rj.base_commit, unequal, loop: loop.summary, baseline: baseline.summary, loop_extra_usd: extra, also, verdict: v }
  if (values.json) {
    console.log(JSON.stringify(report, null, 2))
    return v.kind === "withheld" ? 2 : 0
  }
  const f = (n: number) => `$${n.toFixed(2)}`
  console.log(`compare: loss ${loop.rj.loss.candidate} (${loop.rj.loss.signal} in ${loop.rj.loss.scope}), base ${loop.rj.base_commit.slice(0, 7)}`)
  for (const s of [loop.summary, baseline.summary]) {
    console.log(`  ${s.arm.padEnd(11)} ${s.run}: cap ${f(s.cap_usd)}, fix ${s.fix_launches} launch(es) charged ${f(s.fix_charged_usd)} (reported ${f(s.fix_reported_usd)}), eval charged ${f(s.eval_charged_usd)}, ${Math.round(s.time_ms / 1000)}s of evaluator time; mean pass ${s.mean_pass === null ? "—" : s.mean_pass.toFixed(2)}`)
    for (const r of s.reps) {
      const score = r.voided ? `VOIDED (${r.voided})` : r.pack_failed ? "build/pack FAILED → 0" : r.candidate === null ? "no candidate" : r.pass === undefined ? `${r.candidate}: not yet evaluated` : `${r.candidate}: ${r.pass} pass / ${r.fail} fail on ${(r.sessions ?? []).join(",")} (${r.eval_run})`
      console.log(`    r${r.rep}: ${r.changed ? "changed" : "unchanged"}; ${score}`)
    }
  }
  for (const a of also) console.log(`  also ${a.candidate}: ${a.eval ? `${a.eval.reps.map((r) => `r${r.rep} ${r.pass}/${r.fail}`).join(", ")} on ${a.eval.sessions.join(",")} (${a.eval.run})` : "not evaluated"}`)
  if (unequal.length) for (const u of unequal) console.log(`  ✗ unequal: ${u}`)
  console.log(`  loop full cost: ${v.loop_full_cost_usd === null ? "UNSTATED (pass --loop-extra-usd)" : f(v.loop_full_cost_usd)}; baseline cap ${f(v.baseline_cap_usd)}; full-cost delta (loop − baseline, eval included): ${v.cost_delta_usd === null ? "—" : f(v.cost_delta_usd)}`)
  console.log(`VERDICT ${v.kind.toUpperCase()}: ${v.reason}`)
  return v.kind === "withheld" ? 2 : 0
}

