import { existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { homedir, tmpdir } from "node:os"
import { join } from "node:path"
import {
  type ArmSummary,
  type FixRunJson,
  type RepSummary,
  composeFixPrompt,
  evidenceText,
  exportCell,
  findLossRow,
  hiddenTipShas,
  meanPass,
  renderLossRow,
  resolveEvidence,
  scanTranscript,
  unequalParams,
  verdict,
  worktreesOf,
} from "../lib/fix"
import { candidateProfile, selfTest, tempProfile } from "../lib/sandbox"

// ---------- fixtures ----------

const T = (n: number) => `2026-09-16T08:${String(n).padStart(2, "0")}:00.000Z`
const ev = (id: string, ts: string, type: string, payload: unknown, initiative = "scope-a") => JSON.stringify({ v: 1, id, ts, initiative, session: "cli", source: "cli", actor: "agent", type, payload })

/** A .sofar dir with one scope initiative whose log holds the given events, plus a second initiative that mentions nothing. */
function sofarDir(scopeEvents: string[], other: string[] = []): string {
  const root = mkdtempSync(join(tmpdir(), "evaluator-fix-"))
  const sofar = join(root, ".sofar")
  mkdirSync(join(sofar, "initiatives", "scope-a"), { recursive: true })
  mkdirSync(join(sofar, "initiatives", "other"), { recursive: true })
  writeFileSync(join(sofar, "initiatives", "scope-a", "events.jsonl"), `${scopeEvents.join("\n")}\n`)
  writeFileSync(join(sofar, "initiatives", "other", "events.jsonl"), `${other.join("\n")}\n`)
  return sofar
}

const HASH = "0123456789abcdef"
const TRUST = { protocol: "P1", verdict: "V1", precision: 0.97, recall: 0.53, judged: 29 }
const proposed = ev("01PROPOSED", T(1), "suggestion_proposed", { candidate: HASH, signal: "corrections", evidence: ["01EV1", "01EV2", "row:abc"], count: 1, cutoff: "01CUT", engine: "0.32.0", detector_version: 1, trust: TRUST })
const approved = ev("01APPROVED", T(2), "suggestion_approved", { candidate: HASH, reason: "real loss" })
const rejected = ev("01REJECTED", T(3), "suggestion_rejected", { candidate: HASH, reason: "no" })
const reverted = ev("01REVERTED", T(3), "suggestion_reverted", { candidate: HASH, reason: "undo" })
const evidence = [ev("01EV1", T(0), "note_added", { text: "the   agent kept\nrepeating itself" }), ev("01EV2", T(0), "correction", { ref: "01EV1", reason: "wrong id" })]

describe("the approved loss row (D13 §2)", () => {
  test("only a row whose LAST transition is approved enters a cycle", () => {
    const ok = findLossRow(sofarDir([...evidence, proposed, approved]), HASH)
    expect(ok.ok).toBe(true)
    if (ok.ok) {
      expect(ok.row.scope).toBe("scope-a")
      expect(ok.row.approved.event).toBe("01APPROVED")
      expect(ok.row.evidence).toEqual(["01EV1", "01EV2", "row:abc"])
      expect(ok.row.trust.precision).toBe(0.97)
    }
    const recorded = findLossRow(sofarDir([proposed]), HASH)
    expect(recorded.ok).toBe(false)
    if (!recorded.ok) expect(recorded.reason).toContain("recorded but not approved")
    const rej = findLossRow(sofarDir([proposed, rejected]), HASH)
    if (!rej.ok) expect(rej.reason).toContain("rejected")
    const rev = findLossRow(sofarDir([proposed, approved, reverted]), HASH)
    expect(rev.ok).toBe(false)
    if (!rev.ok) expect(rev.reason).toContain("reverted")
    const none = findLossRow(sofarDir([approved]), HASH)
    expect(none.ok).toBe(false)
    if (!none.ok) expect(none.reason).toContain("no suggestion_proposed")
    expect(findLossRow(sofarDir([]), "ffff").ok).toBe(false)
  })
  test("transitions are found across initiatives and ordered by time", () => {
    // approved in the scope, later reverted from another initiative's log
    const r = findLossRow(sofarDir([proposed, approved], [ev("01REV2", T(9), "suggestion_reverted", { candidate: HASH }, "other")]), HASH)
    expect(r.ok).toBe(false)
  })
  test("the row text is deterministic, names every evidence entry, and says what it could not resolve", () => {
    const dir = sofarDir([...evidence, proposed, approved])
    const r = findLossRow(dir, HASH)
    if (!r.ok) throw new Error(r.reason)
    const text = renderLossRow(r.row, resolveEvidence(r.scopeLog, r.row.evidence))
    expect(text).toBe(renderLossRow(r.row, resolveEvidence(r.scopeLog, r.row.evidence)))
    expect(text).toContain(`Loss row ${HASH}`)
    expect(text).toContain("precision 0.97, recall 0.53 over 29 judged")
    expect(text).toContain("01EV1 2026-09-16T08:00:00.000Z note_added: note: the agent kept repeating itself")
    expect(text).toContain("01EV2 2026-09-16T08:00:00.000Z correction: correction of 01EV1: wrong id")
    expect(text).toContain("row:abc: a private diagnostics row, not in the record")
    expect(evidenceText({ type: "decision_logged", payload: { chose: "x".repeat(500) } }).length).toBeLessThan(420)
  })
})

describe("the prompt (D13 §1, §4)", () => {
  test("direct-fix is a strict prefix of loop-fix: the brief is the only difference", () => {
    const row = "Loss row X\n"
    const direct = composeFixPrompt({ arm: "direct-fix", base: "abc123", rowText: row })
    const loop = composeFixPrompt({ arm: "loop-fix", base: "abc123", rowText: row, brief: "Try the fold first.\n" })
    expect(loop.startsWith(direct.trimEnd())).toBe(true)
    expect(loop.slice(direct.trimEnd().length)).toBe("\n\nBrief from the improvement loop:\nTry the fold first.\n")
    expect(direct).toContain("`npm test`, `npm run typecheck`, `npm run build`")
    expect(direct).not.toContain("hidden")
    // a brief handed to direct-fix is ignored, never appended
    expect(composeFixPrompt({ arm: "direct-fix", base: "abc123", rowText: row, brief: "leak" })).toBe(direct)
  })
})

describe("the refless cell (D13 §3)", () => {
  test("git archive of one commit into a one-commit repo: the other branch is unreachable, the hidden record is gone", async () => {
    const root = mkdtempSync(join(tmpdir(), "evaluator-cell-"))
    const src = join(root, "src")
    mkdirSync(src)
    const sh = (cmd: string) => {
      const r = Bun.spawnSync(["/bin/sh", "-c", cmd], { cwd: src, env: { ...process.env, GIT_AUTHOR_NAME: "t", GIT_AUTHOR_EMAIL: "t@t", GIT_COMMITTER_NAME: "t", GIT_COMMITTER_EMAIL: "t@t" } })
      if (r.exitCode !== 0) throw new Error(`${cmd}: ${r.stderr.toString()}`)
      return r.stdout.toString().trim()
    }
    sh("git init -q -b main && mkdir -p .sofar/initiatives/keep .sofar/initiatives/secret-plan && echo a > a.txt && echo k > .sofar/initiatives/keep/events.jsonl && echo s > .sofar/initiatives/secret-plan/events.jsonl && git add -A && git commit -q -m base")
    const base = sh("git rev-parse HEAD")
    sh("git checkout -q -b secret && echo 'the answer' > answer.txt && git add -A && git commit -q -m secret && git checkout -q main")
    const secret = sh("git rev-parse secret")
    const dest = join(root, "cell", "repo")
    const out = await exportCell({ repo: src, commit: base, dest, hideRecords: ["secret-plan", "absent"] })
    expect(out.removed).toEqual(["secret-plan"])
    const inCell = (cmd: string) => Bun.spawnSync(["/bin/sh", "-c", cmd], { cwd: dest })
    expect(inCell("git rev-list --all --count").stdout.toString().trim()).toBe("1")
    expect(inCell("git cat-file -e " + secret).exitCode).not.toBe(0)
    expect(inCell("git rev-parse --verify secret").exitCode).not.toBe(0)
    expect(existsSync(join(dest, "answer.txt"))).toBe(false)
    expect(existsSync(join(dest, "a.txt"))).toBe(true)
    expect(existsSync(join(dest, ".sofar", "initiatives", "keep"))).toBe(true)
    expect(existsSync(join(dest, ".sofar", "initiatives", "secret-plan"))).toBe(false)
    expect(inCell("git log -1 --format=%s").stdout.toString().trim()).toBe(`base: ${base}`)
    // the hidden tips are every other branch tip; the worktree list starts with the main one
    expect(await hiddenTipShas(src, base)).toEqual([secret])
    expect((await worktreesOf(src))[0]).toBe(sh("pwd -P"))
    rmSync(root, { recursive: true, force: true })
  })
})

