// ---------- equal parameters and the verdict (D13 §6, §7) ----------

const runJson = (arm: FixRunJson["arm"], extra: Partial<FixRunJson> = {}): FixRunJson => ({
  mode: "fix",
  run: `${arm}-run`,
  arm,
  loss: { candidate: HASH, scope: "scope-a", signal: "corrections", approved_event: "01APPROVED" },
  row_sha256: "r".repeat(64),
  prompt_sha256: "p".repeat(64),
  brief_sha256: arm === "loop-fix" ? "b".repeat(64) : null,
  base_commit: "c".repeat(40),
  source_repo: "/src",
  hidden: { paths: ["/src"], records: [], void_terms: 1 },
  model: "haiku",
  effort: "high",
  timeout_min: 30,
  reps: 1,
  pin_hash: "pin",
  evaluator: { commit: "e".repeat(40), dirty: [] },
  budget: { runMaxUsd: 20, weekUsd: 450, windowUsd: 150, nextSessionUsd: 8, maxLaunches: 1 },
  started_at: T(5),
  ...extra,
})

const rep = (n: number, extra: Partial<RepSummary> = {}): RepSummary => ({ rep: n, candidate: `cand-${n}`, voided: null, changed: true, pack_failed: false, eval_run: "ev", sessions: ["S1"], pass: 7, fail: 1, ...extra })
const arm = (a: ArmSummary["arm"], reps: RepSummary[], extra: Partial<ArmSummary> = {}): ArmSummary => ({ arm: a, run: `${a}-run`, reps, fix_launches: reps.length, fix_charged_usd: 2, fix_reported_usd: 2, eval_charged_usd: 1, time_ms: 1000, cap_usd: 20, mean_pass: meanPass(reps), ...extra })

describe("equal parameters (D13 §1)", () => {
  test("the brief and the hidden set may differ; everything else must match", () => {
    expect(unequalParams(runJson("loop-fix"), runJson("direct-fix", { hidden: { paths: [], records: ["r1-fixes"], void_terms: 0 } }))).toEqual([])
    const u = unequalParams(runJson("loop-fix"), runJson("direct-fix", { model: "opus", reps: 3, row_sha256: "x".repeat(64) }))
    expect(u.map((s) => s.split(":")[0])).toEqual(["row_sha256", "model", "reps"])
  })
})

describe("the verdict (D13 §6, §7)", () => {
  test("keep only on a strict win at a baseline cap covering the loop's full cost; a tie loses", () => {
    const keep = verdict({ loop: arm("loop-fix", [rep(1, { pass: 8 })]), baseline: arm("direct-fix", [rep(1, { pass: 7 })]), loopExtraUsd: 3, unequal: [] })
    expect(keep.kind).toBe("keep")
    expect(keep.loop_full_cost_usd).toBe(5)
    expect(keep.cost_delta_usd).toBeCloseTo(5 + 1 - (2 + 1), 6)
    expect(verdict({ loop: arm("loop-fix", [rep(1, { pass: 7 })]), baseline: arm("direct-fix", [rep(1, { pass: 7 })]), loopExtraUsd: 0, unequal: [] }).kind).toBe("discard")
    expect(verdict({ loop: arm("loop-fix", [rep(1, { pass: 6 })]), baseline: arm("direct-fix", [rep(1, { pass: 7 })]), loopExtraUsd: 0, unequal: [] }).kind).toBe("discard")
  })
  test("withheld: unequal params, unstated loop cost, a voided rep, a missing eval, a cap below the loop's full cost, mixed session sets", () => {
    const L = arm("loop-fix", [rep(1, { pass: 9 })])
    const B = arm("direct-fix", [rep(1, { pass: 1 })])
    expect(verdict({ loop: L, baseline: B, loopExtraUsd: 0, unequal: ["model: x vs y"] }).reason).toContain("unequal parameters")
    expect(verdict({ loop: L, baseline: B, loopExtraUsd: null, unequal: [] }).reason).toContain("--loop-extra-usd")
    expect(verdict({ loop: arm("loop-fix", [rep(1, { voided: "named a tip" })]), baseline: B, loopExtraUsd: 0, unequal: [] }).reason).toContain("voided")
    expect(verdict({ loop: L, baseline: arm("direct-fix", [rep(1, { pass: undefined, eval_run: undefined })]), loopExtraUsd: 0, unequal: [] }).reason).toContain("no evaluation run")
    const capped = verdict({ loop: arm("loop-fix", [rep(1, { pass: 9 })], { fix_charged_usd: 15 }), baseline: arm("direct-fix", [rep(1, { pass: 1 })], { cap_usd: 20 }), loopExtraUsd: 6, unequal: [] })
    expect(capped.kind).toBe("withheld")
    expect(capped.reason).toContain("below the loop's full cost $21.00")
    expect(verdict({ loop: L, baseline: arm("direct-fix", [rep(1, { sessions: ["S1", "S2"] })]), loopExtraUsd: 0, unequal: [] }).reason).toContain("different session sets")
  })
  test("a fix that failed to build scores 0 and never withholds; the mean is over every rep", () => {
    const reps = [rep(1, { pass: 8 }), rep(2, { candidate: null, pack_failed: true, pass: undefined, sessions: undefined, eval_run: undefined })]
    expect(meanPass(reps)).toBe(4)
    const v = verdict({ loop: arm("loop-fix", reps), baseline: arm("direct-fix", [rep(1, { pass: 3 }), rep(2, { pass: 3 })]), loopExtraUsd: 0, unequal: [] })
    expect(v.kind).toBe("keep")
    expect(verdict({ loop: arm("loop-fix", [rep(1, { candidate: null, pack_failed: true, pass: undefined })]), baseline: arm("direct-fix", [rep(1, { pass: 0 })]), loopExtraUsd: 0, unequal: [] }).kind).toBe("discard")
  })
})

