import json, os, re, glob, collections, sys
from sessions import sid_map, cell_proj
SOFAR_CMD = re.compile(r"(^|[\s;&|(`'\"])sofar(\s|$|['\"])")
def is_store(arm, name, text):
    if arm=='claude-sofar':
        return name.startswith('mcp__sofar') or (name=='ToolSearch' and 'sofar' in text) or '.sofar/' in text or bool(SOFAR_CMD.search(text))
    if arm=='claude-automemory':
        return 'claude-config/projects/' in text and '/memory' in text
def load(path):
    rows=[]; results={}; msgs={}
    for l in open(path):
        e=json.loads(l); t=e.get('type')
        if t=='assistant':
            m=e['message']; mid=m.get('id')
            msgs.setdefault(mid,{'out':0,'blocks':[]})
            msgs[mid]['out']=max(msgs[mid]['out'],(m.get('usage') or {}).get('output_tokens') or 0)
            for b in m.get('content') or []:
                msgs[mid]['blocks'].append(b)
                if b.get('type')=='tool_use':
                    rows.append({'id':b['id'],'name':b['name'],'input':b.get('input'),'mid':mid,'ts':e.get('timestamp')})
        elif t=='user':
            c=(e.get('message') or {}).get('content')
            if isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='tool_result':
                        body=b.get('content'); body=body if isinstance(body,str) else json.dumps(body,ensure_ascii=False)
                        results[b['tool_use_id']]={'len':len(body),'err':bool(b.get('is_error')),'body':body}
    return rows, results, msgs
def classify_sofar(r):
    n=r['name']; inp=json.dumps(r['input'],ensure_ascii=False)
    if n.startswith('mcp__sofar__'):
        k=n.replace('mcp__sofar__sofar_','')
        if k=='log_decision': k+= '+rule' if (r['input'] or {}).get('rule') else '-norule'
        return k
    if n=='ToolSearch': return 'ToolSearch(load sofar tools)'
    cmd=(r['input'] or {}).get('command','') if n=='Bash' else ''
    if n in('Edit','Write') or re.search(r"cat\s*>|>>|tee ", cmd) and '.sofar' in cmd: 
        return 'write .sofar file (repo.md etc)' if n in ('Edit','Write') or '.sofar/repo.md' in cmd else 'bash write .sofar'
    if n=='Read' or n=='Bash': 
        if 'biome' in inp or 'lint' in inp: return 'lint/config touching .sofar'
        return 'read .sofar files (plan/decisions/repo.md)'
    return 'other:'+n
def classify_am(r):
    n=r['name']; cmd=(r['input'] or {}).get('command','') if n=='Bash' else ''
    if n in ('Write','Edit'): return 'write memory file'
    if n=='Read': return 'read memory file'
    if n=='Bash':
        if re.search(r"cat\s*>|<<|>>|tee |sed -i|python3? - <<|rm |mv ", cmd): return 'bash write memory'
        return 'bash read memory'
    return 'other:'+n
if __name__=='__main__':
    for arm,rep in [("claude-sofar",1),("claude-sofar",3),("claude-automemory",1),("claude-automemory",3)]:
        agg=collections.defaultdict(lambda: collections.Counter())
        tot=collections.Counter()
        for s,d in sid_map(arm,rep).items():
            sid=d['session_id']; p=os.path.join(cell_proj(arm,rep),f"{sid}.jsonl")
            files=[p]+glob.glob(os.path.join(cell_proj(arm,rep),sid,'subagents','*.jsonl'))
            for f in files:
                rows,res,msgs=load(f)
                store_mids=set()
                for r in rows:
                    inp=json.dumps(r['input'],ensure_ascii=False)
                    tot['calls']+=1
                    if not is_store(arm,r['name'],inp): continue
                    c=classify_sofar(r) if arm=='claude-sofar' else classify_am(r)
                    rr=res.get(r['id'],{'len':0,'err':False})
                    agg[c]['calls']+=1; agg[c]['in_chars']+=len(inp); agg[c]['res_chars']+=rr['len']; agg[c]['errors']+=rr['err']
                    tot['store']+=1; store_mids.add(r['mid'])
                    # message out tokens attributed once per message to first store class
                    agg[c]['_mids']+=0
                for mid,m in msgs.items():
                    tot['out']+=m['out']
                    if mid in store_mids:
                        tot['store_out']+=m['out']
                        # attribute message out to classes proportionally by count of store calls in message
                        cls=[ (classify_sofar(r) if arm=='claude-sofar' else classify_am(r)) for r in rows if r['mid']==mid and is_store(arm,r['name'],json.dumps(r['input'],ensure_ascii=False))]
                        nonstore=[r for r in rows if r['mid']==mid and not is_store(arm,r['name'],json.dumps(r['input'],ensure_ascii=False))]
                        if nonstore: tot['mixed_msgs']+=1; tot['mixed_out']+=m['out']
                        for c in cls: agg[c]['msg_out']+=m['out']/len(cls)
        print('==',arm,rep,dict(tot), 'share calls %.1f%% out %.1f%%'%(100*tot['store']/tot['calls'],100*tot['store_out']/tot['out']))
        print(f"   {'class':45} calls  in_chars(~tok) res_chars errors msg_out_tok")
        for c,v in sorted(agg.items(), key=lambda x:-x[1]['calls']):
            print(f"   {c:45} {v['calls']:5} {v['in_chars']:8} ({v['in_chars']//4:6}) {v['res_chars']:8} {v['errors']:3} {int(v['msg_out']):8}")
