/** The round-1 loss study's observable columns. The "fixed in RC?" column is never read: it can name the fix. */
export interface LossStudyRow {
  id: string
  klass: string
  loss: string
  scope: string
  source: string
  source_sha256: string
}

export const LOSS_STUDY_ID = /^L\\d{2,}$/

/**
 * One `| L11 | S | loss | scope | fixed in RC? |` row of the loss-study table.
 * Only class S (a sofar loss) enters a fix cycle; H, T and A rows are the
 * harness's, the tests' or the agent's, and no sofar change can remove them.
 */
export function findLossStudyRow(file: string, id: string): { ok: true; row: LossStudyRow } | { ok: false; reason: string } {
  if (!LOSS_STUDY_ID.test(id)) return { ok: false, reason: `${id} is not a loss-study id (L01, L11, …)` }
  if (!existsSync(file)) return { ok: false, reason: `no loss study at ${file}` }
  const text = readFileSync(file, "utf8")
  const hits = text.split("\\n").filter((l) => l.startsWith(`| ${id} |`))
  if (hits.length !== 1) return { ok: false, reason: `${hits.length} rows for ${id} in ${file}; exactly one is required` }
  const cells = hits[0]!.split("|").slice(1, -1).map((c) => c.trim())
  if (cells.length < 5) return { ok: false, reason: `row ${id} has ${cells.length} columns; expected id, class, loss, scope, fixed-in-RC` }
  // A pipe inside the loss text splits it: the loss is everything between class and the last two columns.
  const [rid, klass] = cells as [string, string]
  const loss = cells.slice(2, -2).join(" | ")
  const scope = cells[cells.length - 2]!
  if (klass !== "S") return { ok: false, reason: `${id} is class ${klass}, not S (a sofar loss); only a sofar loss enters a fix cycle (D15)` }
  return { ok: true, row: { id: rid, klass, loss, scope, source: file, source_sha256: sha256(text) } }
}

/** Byte-identical for both arms; the source path is never named (the cell cannot read it, and it holds the fix table). */
