 * `--hidden-commit` is absent from the cell's object store, and the cell's
 * history is exactly one commit. Returns the problems; empty means it holds.
 */
export async function unreachableInCell(cellRepo: string, commits: string[]): Promise<string[]> {
  const problems: string[] = []
  const count = (await gitOut(cellRepo, ["rev-list", "--all", "--count"], "git rev-list")).trim()
  if (count !== "1") problems.push(`cell history has ${count} commits reachable from --all; expected 1`)
  const reflog = await run(["git", "reflog", "--all", "--format=%H"], { cwd: cellRepo, timeoutMs: 60_000 })
  const reflogShas = new Set(reflog.stdout.split("\\n").filter(Boolean))
  if (reflogShas.size > 1) problems.push(`cell reflog names ${reflogShas.size} commits; expected 1`)
  for (const c of commits) {
    const r = await run(["git", "cat-file", "-e", `${c}^{commit}`], { cwd: cellRepo, timeoutMs: 60_000 })
    if (r.code === 0) problems.push(`hidden commit ${c} is present in the cell's object store`)
  }
  return problems
